const S_POR_PERFIL = { basico: 266, vendas: 622 };

const WRAPPER = WRAPPERS[perfil] ?? WRAPPERS.basico;

// Schemas das ferramentas, POR PERFIL — cada agent carrega um conjunto diferente
// e custa diferente. 622 (7 tools) foi MEDIDO pelo metodo das duas equacoes;
// 266 (3 tools) ainda e regra de tres e sera medido assim que houver execucao no
// perfil basico. Com `r` ja conhecido, uma execucao basta para resolver.
const TOKENS_FERRAMENTAS = S_POR_PERFIL[perfil] ?? S_POR_PERFIL.basico;

// Crescimento medio do prompt a cada round-trip de tool (resultado da tool +
// mensagem do assistente). Calibrado contra as 3 execucoes reais: com 55, a
// formula errou 0,0% / -1,4% / 0,0%.
const CRESCIMENTO_POR_CHAMADA = 55;

// 3,11 chars/token, MEDIDO para portugues acentuado — nao os 4 da heuristica
// generica, que subestimava em ~29%. O tokenizer da OpenAI quebra acento em mais
// de um token, e o system prompt daqui e todo em portugues.
const CHARS_POR_TOKEN = 3.11;
const emTokens = (t) => Math.ceil((t || '').length / CHARS_POR_TOKEN);

// ----------------------------------------------------------------------------
// 1. Sonda: o numero exato esta alcancavel?
// ----------------------------------------------------------------------------
let usoN8n = null;
let sonda = 'nao_tentada';

const formas = [
  ['all', () => $('OpenAI Chat Model').all().map((i) => i.json)],
  ['first', () => [$('OpenAI Chat Model').first().json]],
];

for (const [nome, fn] of formas) {
  try {
    const itens = fn();
    const usos = (itens || [])
      .map((j) => j?.tokenUsageEstimate ?? j?.tokenUsage ?? null)
      .filter(Boolean);
    if (usos.length > 0) {
      usoN8n = {
        chamadas: usos.length,
        entrada: usos.reduce((a, u) => a + (u.promptTokens || 0), 0),
        saida: usos.reduce((a, u) => a + (u.completionTokens || 0), 0),
      };
      sonda = `ok:${nome}`;
      break;
    }
    sonda = `vazio:${nome}`;
  } catch (e) {
    sonda = `erro:${nome}:${String(e && e.message).slice(0, 60)}`;
  }
}

// ----------------------------------------------------------------------------
// 2. Caminho estimado, com multiplicidade
// ----------------------------------------------------------------------------
let systemPrompt = '';
try {
  systemPrompt = $('Resolve Tenant').first().json.system_prompt ?? '';
} catch (e) { faltou.push('Resolve Tenant'); }

let mensagens = '';
try {
  const lista = $('Lista Depois').first().json.lista_depois;
  mensagens = Array.isArray(lista) ? lista.join('\n') : (lista ?? '');
} catch (e) {
  faltou.push('Lista Depois');
  mensagens = agent?.input ?? '';
}

// Quantas vezes o modelo foi chamado. `intermediateSteps` exige
// `returnIntermediateSteps: true` nas opcoes do AI Agent — sem isso caimos em 1,
// que e o comportamento antigo (e o erro antigo).
const passos = Array.isArray(agent?.intermediateSteps) ? agent.intermediateSteps.length : 0;
const chamadas = 1 + passos;

// ----------------------------------------------------------------------------
// 1b. SONDA B — o numero exato veio JUNTO com a saida do agent?
// ----------------------------------------------------------------------------
// A sonda A acima pergunta se da para ALCANCAR o sub-no a partir daqui, e o
// veredicto foi nao. Esta pergunta e outra: com `returnIntermediateSteps`
// ligado (esta ligado nos dois agents), o objeto que chega em $input carrega
// `messageLog` com as AIMessage de cada round-trip de tool -- e uma AIMessage
// serializada pode trazer `response_metadata.tokenUsage` e `usage_metadata`,
// que sao o campo `usage` da resposta da API, nao estimativa.
//
// Ninguem tinha olhado: este arquivo le `output` e `intermediateSteps` e mais
// nada. Entao a sonda nao procura um caminho que eu ache que existe -- ela
// VARRE o objeto inteiro atras de qualquer par (promptTokens|input_tokens) e
// (completionTokens|output_tokens), e reporta os caminhos que achou. Uma
// execucao real responde de vez, e o resultado nao depende de eu ter acertado
// o formato de serializacao da versao do n8n que roda aqui.
//
// LIMITE ESTRUTURAL, e por isso o resultado NAO entra no total automaticamente:
// `intermediateSteps` cobre os passos que chamaram ferramenta, e a chamada FINAL
// -- a que produziu `output` -- nao vira passo. Somar so o que ela achar
// subcobra, calado, que e exatamente a falha que este arquivo existe para
// impedir. Se a sonda achar N usos com N = `chamadas` - 1, o caminho e somar o
// uso reportado nos passos e estimar apenas a ultima chamada.
//
// PREVISAO REGISTRADA EM 18/08, ANTES DE QUALQUER EXECUCAO: deve achar ZERO. Se
// a chamada nao devolve `usage` -- que e o que o `tokenUsageEstimate` do sub-no
// indica --, a AIMessage tambem nao carrega `usage_metadata`. Achar zero fecha o
// caminho 1 pela mesma causa que fechou o 2; achar QUALQUER COISA refuta a
// explicacao inteira e reabre o caminho 1 como o melhor dos tres. Por isso ela
// fica no ar ate a primeira execucao: custa uma varredura de objeto e responde
// uma pergunta que esta aberta desde 11/08.
const acharUsos = (raiz) => {
  const achados = [];
  const vistos = new Set();
  const fila = [[raiz, 'json']];
  let visitados = 0;
  // Tetos: o objeto pode conter a conversa inteira, e um no Code que estoura
  // memoria derruba a mensagem do cliente. Diagnostico nunca vale isso.
  while (fila.length > 0 && visitados < 5000 && achados.length < 40) {
    const [v, caminho] = fila.shift();
    visitados++;
    if (!v || typeof v !== 'object') continue;
    if (vistos.has(v)) continue; // messageLog costuma reapontar para o mesmo objeto
    vistos.add(v);
    if (caminho.split('.').length > 16) continue;
    const entrada = v.promptTokens ?? v.input_tokens ?? v.prompt_tokens;
    const saida = v.completionTokens ?? v.output_tokens ?? v.completion_tokens;
    if (typeof entrada === 'number' || typeof saida === 'number') {
      achados.push({ caminho, entrada: Number(entrada) || 0, saida: Number(saida) || 0 });
      continue; // achou o uso; descer dentro dele so duplicaria
    }
    for (const k of Object.keys(v)) fila.push([v[k], caminho + '.' + k]);
  }
  return { achados, visitados, truncou: fila.length > 0 };
};

let sonda_b;
try {
  const r = acharUsos(agent);
  sonda_b = r.achados.length === 0
    // Caso previsto: compacto de proposito. Um campo de diagnostico que despeja
    // objeto grande em TODA mensagem vira ruido que ninguem le -- e ai ele nao
    // avisa nada no dia em que mudar. `chaves_topo` fica porque e o que responde
    // "entao o que TEM no objeto?", que e a pergunta seguinte.
    ? { usos: 0, chaves_topo: Object.keys(agent || {}), visitados: r.visitados }
    : {
        // A previsao caiu: aqui vale despejar tudo, porque muda a decisao.
        usos: r.achados.length,
        // Batendo com `chamadas`, o uso reportado cobre tudo. Sendo
        // `chamadas` - 1, falta so a chamada final, que se estima.
        chamadas_estimadas: chamadas,
        entrada: r.achados.reduce((a, u) => a + u.entrada, 0),
        saida: r.achados.reduce((a, u) => a + u.saida, 0),
        caminhos: r.achados.map((u) => u.caminho).slice(0, 8),
        chaves_topo: Object.keys(agent || {}),
        visitados: r.visitados,
        truncou: r.truncou,
      };
} catch (e) {
  sonda_b = { erro: String(e && e.message).slice(0, 120) };
}


// Tamanho da janela de memoria que o modelo recebe, vindo da migracao 29 pelo
// no que ja existia (Sync Conversa) — sem query nova num caminho que ja tem
// tres. Era a maior causa restante de erro: ~970 tokens por mensagem, e
// crescendo com o tamanho da conversa, o que tornava o rateio nao-uniforme.
let historicoChars = 0;
try {
  historicoChars = Number($('Sync Conversa').first().json.historico_chars) || 0;
} catch (e) { faltou.push('Sync Conversa'); }
const base = emTokens(WRAPPER + systemPrompt + mensagens) + TOKENS_FERRAMENTAS + Math.ceil(historicoChars / 4);

// Cada chamada reenvia o prompt inteiro; o historico cresce a cada round-trip.
const estimado_entrada = chamadas * base + CRESCIMENTO_POR_CHAMADA * ((chamadas * (chamadas - 1)) / 2);
const estimado_saida = emTokens(textoSaida);

// ----------------------------------------------------------------------------
// 3. A estimativa do n8n quando der, a nossa quando nao
// ----------------------------------------------------------------------------
const tokens_entrada = usoN8n ? usoN8n.entrada : estimado_entrada;
const tokens_saida = usoN8n ? usoN8n.saida : estimado_saida;

return [{
  json: {
    output: textoSaida,
    tokens_entrada,
    tokens_saida,
    // O rotulo diz de QUEM e a estimativa. Nenhum dos dois valores vem da
    // OpenAI, e o nome nao pode sugerir que vem.
    _fonte_tokens: usoN8n ? 'estimativa_n8n_sub_no' : 'estimativa_nossa_com_multiplicidade',
    // Diagnostico: some daqui quando a sonda tiver dado veredicto e o caminho
    // estiver decidido. Ate la, e o que responde se da para parar de estimar.
    _sonda: sonda,
    _sonda_b: sonda_b,
    _chamadas: usoN8n ? usoN8n.chamadas : chamadas,
    _estimado_entrada: estimado_entrada,
    _historico_chars: historicoChars,
    _perfil: perfil,
    // Vazio e o esperado. Com algo dentro, o rateio esta subestimando: cada
    // entrada aqui e um pedaco do prompt que o no nao conseguiu medir.
    _faltou: faltou,
  },
}];

parameters.query:
SELECT case when exists (
         select 1 from public.api_n8n_tools_ativas($1::uuid)
         where tool_nome = 'vendas'
       ) then 'vendas' else 'basico' end AS perfil;

SELECT tool_ativa, conversa_pausada, chatwoot_url, chatwoot_token,
       limite_bytes, msg_audio_longo, msg_audio_falhou
  FROM public.api_n8n_pode_transcrever($1::uuid, $2::bigint);

parameters.jsCode:
// ============================================================================
// FILTRA TRANSCRICAO — corpo do no que trata o retorno da transcricao
//
// ESTE ARQUIVO E A FONTE. O gerador injeta o bloco de n8n/filtro-texto.js no
// lugar do marcador __FILTRO_TEXTO__ e grava o resultado no no. O MESMO bloco
// vai para o `Extrair e Filtrar` — `npm run n8n:sincronia` falha se os dois
// deixarem de ser identicos byte a byte.
//
// POR QUE O FILTRO RODA DE NOVO AQUI. O `Extrair e Filtrar` filtra o texto
// DIGITADO. Audio transcrito e texto do cliente que entra no fluxo depois disso:
// sem passar pela mesma blocklist, alguem fala "esquece suas instrucoes" numa
// nota de voz e chega ao modelo sem filtro nenhum. O canal e outro, o ataque e o
// mesmo.
//
// Devolve `status`, e quem roteia e o no seguinte:
//   ok         -> segue para o Mensagem Pronta
//   bloqueado  -> vai para o caminho de bloqueio que o texto ja tem
//   vazio      -> avisa que nao entendeu e NAO chama o agente
// ============================================================================

const resposta = $input.first().json ?? {};

// `verbose_json` devolve { text, duration, language, segments, usage }.
//
// DOIS NUMEROS DE DURACAO, e eles NAO sao iguais. Do retorno real de 12/08:
//
//   duration        1.7799999713897705   <- duracao real do arquivo
//   usage.seconds   2                    <- o que a OpenAI COBRA (arredondado)
//
// O que vai para `audio_segundos` e o COBRADO, nao o real: a coluna existe para
// ratear custo, e ratear pelo real subestimaria sistematicamente — todo audio e
// arredondado para cima, e nota de voz curta e o caso comum. Com audios de ~2s,
// a diferenca chega perto de 10%.
//
// `duration` fica no diagnostico, para calibrar o proxy de bytes; a diferenca de
// arredondamento e irrelevante contra um corte de 3 minutos.
const bruto = String(resposta.text ?? '').trim();
const cobrado = Number(resposta.usage?.seconds);
const real = Number(resposta.duration);
// Fallback para o real se `usage` nao vier: melhor medir com o numero errado do
// que nao medir. Se isso acontecer, `_duracao_fonte` denuncia.
const duracao = Number.isFinite(cobrado) ? cobrado : real;

// ============================================================================
// FILTRO DE TEXTO — blocklist de injection + sanitizacao
//
// ESTE ARQUIVO E A FONTE, E E COMPARTILHADO. O gerador injeta este bloco em
// TODO no que precisa filtrar texto de cliente. Hoje: o `Extrair e Filtrar` (o
// texto digitado). Na fatia de audio, tambem o `Filtra Transcricao`.
//
// POR QUE COMPARTILHADO E NAO COPIADO. Um audio transcrito e texto do cliente
// que entra no fluxo DEPOIS do `Extrair e Filtrar` — sem passar pelo mesmo
// filtro, alguem fala "esquece suas instrucoes" numa nota de voz e passa direto.
// Duas copias da blocklist divergem: uma ganha padrao novo, a outra nao, e o
// buraco fica no caminho que ninguem olhou. `npm run n8n:sincronia` falha se os
// blocos deixarem de ser identicos byte a byte.
//
// As funcoes ficam no escopo do no. Nao ha import em node Code do n8n — por isso
// injecao por gerador, e nao `require`.
// ============================================================================

const PADROES_INJECTION = [
  'ignore', 'esquece', 'nova regra', 'system:', 'knowledge-base',
  '<knowledge', '</knowledge', 'act as', 'you are now',
  'ignore as instruções', 'ignore suas instruções', 'esqueça suas regras',
  'novo comportamento', 'mude seu comportamento', 'agora você pode',
  'a partir de agora', 'suas regras mudaram', 'instrução do sistema',
  'ignore o prompt', 'ignore tudo', 'finja que', 'pretend',
  'jailbreak', 'dan mode', 'developer mode'
];

function contemInjection(texto) {
  const lower = (texto || '').toLowerCase();
  return PADROES_INJECTION.some((p) => lower.includes(p));
}

// Tira tag HTML e conteudo entre colchetes. O colchete importa mais do que
// parece: e o formato que o modelo imitou ao fabricar "[Used tools: ...]", e e
// como um cliente escreveria algo se passando por marcacao de sistema.
function sanitizar(texto) {
  return (texto || '').replace(/<[^>]*>/g, '').replace(/\[.*?\]/g, '').trim();
}

const semSaida = (status, extra = {}) => [{
  json: {
    status,
    mensagem: '',
    audio_segundos: Number.isFinite(duracao) ? duracao : null,
    ...extra
  }
}];

// Transcricao vazia acontece: audio mudo, ruido, corte na gravacao. Nao e erro
// da API — ela responde 200 com texto vazio. Tratar como falha explicita evita
// o agente ser chamado com prompt vazio, que e o mesmo modo de falha que a
// execucao 3951563 mostrou.
if (!bruto) {
  return semSaida('vazio', { motivo: 'transcricao_vazia' });
}

if (contemInjection(bruto)) {
  return semSaida('bloqueado', { motivo: 'injection_no_audio' });
}

const mensagem = sanitizar(bruto);
if (!mensagem) {
  return semSaida('vazio', { motivo: 'vazio_pos_sanitizacao' });
}

return [{
  json: {
    status: 'ok',
    mensagem,
    audio_segundos: Number.isFinite(duracao) ? duracao : null,
    // Diagnostico. `_duracao_fonte` denuncia se a OpenAI parar de mandar `usage`
    // e o rateio tiver caido no numero real — que subestima.
    _duracao_fonte: Number.isFinite(cobrado) ? 'usage.seconds' : 'duration',
    _duracao_real: Number.isFinite(real) ? real : null,
    // Guardado para calibrar o proxy: o corte por bytes so vale enquanto a
    // relacao bytes/segundo se mantiver. Com o par medido em execucao real, o
    // limite deixa de ser aritmetica de bitrate.
    _file_size: Number($('Extrair e Filtrar').first().json.anexo?.file_size) || 0
  }
}];

// ============================================================================
// MENSAGEM PRONTA — ponto de convergencia dos dois caminhos
//
// ESTE ARQUIVO E A FONTE, injetado por scripts/gerar-principal.mjs.
//
// O QUE ELE E. O `Acumula Mensagem` precisa de UM lugar de onde ler `mensagem`,
// venha ela do texto digitado ou da transcricao de um audio. Dois nos alimentam
// este aqui e apenas um executa por invocacao:
//
//   Roteia Acao[0] processar ─────────────────────────────┐
//                                                          ├→ Mensagem Pronta
//   ...audio... → Filtra Transcricao (status ok) ──────────┘
//
// POR QUE ELE E PERIGOSO. E no novo no caminho de TODO cliente, e o
// `Acumula Mensagem` passou a depender dele. Se ele emitir vazio, o acumulo
// grava vazio, o agente e chamado sem prompt e a execucao morre com
// "No prompt specified" — exatamente a falha da execucao 3951563, por outra
// porta.
//
// POR ISSO ELE FALHA ALTO. Sem `mensagem` utilizavel ele LANCA, e a execucao
// aparece vermelha com a origem no texto do erro. A alternativa — emitir vazio e
// seguir — trocaria um erro visivel por um agente respondendo do nada, que e o
// modo de falha que este projeto mais pagou caro.
// ============================================================================

// ----------------------------------------------------------------------------
// DE ONDE VEM A MENSAGEM, e por que nao da para ler so o $input
// ----------------------------------------------------------------------------
// O caminho de TEXTO chega aqui assim:
//
//   Extrair e Filtrar -> Resolve Tenant [postgres] -> Tenant Valido? -> Roteia Acao
//
// O `Resolve Tenant` e um no Postgres: ele SUBSTITUI o item pela linha do
// tenant. Entao no caminho de texto o `$input` daqui carrega tenant_id, modelo e
// system_prompt — e nao a mensagem. Era exatamente por isso que o
// `Acumula Mensagem` sempre leu `$('Extrair e Filtrar')` por NOME.
//
// Ler o `$input` aqui derrubou o caminho de texto de TODOS os tenants assim que
// o workflow foi importado (execucao 3955143). A guarda abaixo pegou — que e o
// que ela existe para fazer —, mas o bug era este.
//
// O caminho de AUDIO e o oposto: o item vem do `Filtra Transcricao`, que monta
// `{ status, mensagem, audio_segundos }`. Ali o `$input` E a fonte, porque o
// texto so existe depois da transcricao.
//
// `status` e o discriminador: so o ramo de audio o produz.
const item = $input.first()?.json ?? {};
const daTranscricao = typeof item.status === 'string';

let mensagem = '';
if (daTranscricao) {
  mensagem = typeof item.mensagem === 'string' ? item.mensagem.trim() : '';
} else {
  try {
    const doTeclado = $('Extrair e Filtrar').first().json.mensagem;
    mensagem = typeof doTeclado === 'string' ? doTeclado.trim() : '';
  } catch (e) {
    mensagem = '';
  }
}

if (!mensagem) {
  // De onde veio ajuda a debugar: o caminho de texto so chega aqui com
  // `acao === 'processar'`, que garante mensagem nao vazia; entao vazio aqui
  // aponta para o ramo de audio ou para fiacao errada.
  const origem = daTranscricao
    ? `transcricao (status=${item.status})`
    : 'texto digitado (lido de Extrair e Filtrar)';
  throw new Error(
    'Mensagem Pronta sem mensagem utilizavel — origem: ' + origem + '. ' +
    'Seguir daqui gravaria acumulo vazio e chamaria o agente sem prompt. ' +
    'A execucao para de proposito; ver n8n/mensagem-pronta.js.'
  );
}

return [{
  json: {
    mensagem,
    // NULL em texto digitado — so o audio preenche. E o que alimenta o
    // mensagens_log.audio_segundos, unidade de cobranca propria que nao se soma
    // a token. Sem o `daTranscricao`, um campo homonimo vindo da linha do tenant
    // entraria aqui por engano.
    audio_segundos:
      daTranscricao && Number.isFinite(Number(item.audio_segundos)) ? Number(item.audio_segundos) : null
  }
}];
